<?php
/** TEMP PS S1637 run a — T-0 LIKUČIŲ APPLY (šviežūs 09-07 eksportai; ZB/VF praleidžiamos; pastaba 'Pradinis likutis T-0').
 * Fazės P0–P4: paprastos publish prekės po ~180 (AV: _stock→0 + Partijos::priimti kai sav>0, kitaip _stock=q;
 * tiekėjo prekė su _vf_qty/_zb_qty: _own_stock_qty per priimti / tiesiogiai, _stock NELIEČIAMAS);
 * V: variacijos _stock=q (WC CRUD) + suvestinė. Sena reikšmė → opcija ps_s1637_bak (rollback'ui).
 * Savikaina: eksporto stulpelis → jei 0, WP _cost_price. Partija: importuota=1, pastaba 'Pradinis likutis T-0'. */
add_action('init', function(){
  if (!isset($_GET['ps_s1637a'])) return;
  $f=(string)$_GET['ps_s1637a'];
  if('C'===$f){ global $wpdb; $p=$wpdb->prefix;
    $ist=(int)$wpdb->query("DELETE FROM {$p}ps_partijos WHERE pastaba LIKE 'Pradinis likutis T-0%'"); delete_option('ps_s1637_seen');
    header('Content-Type: application/json'); echo json_encode(array('v'=>'S1637 a C','partiju_istrinta'=>$ist)); exit; }
  $o=array('v'=>'S1637 a '.$f); global $wpdb; $p=$wpdb->prefix;
  if('P0'===$f) $o['temp_istrinta']=(int)$wpdb->query("DELETE FROM {$p}snippets WHERE name LIKE 'TEMP%' AND active=0");
  $sk=$wpdb->get_results("SELECT pm.meta_value sku, pm.post_id, po.post_type, po.post_status FROM {$p}postmeta pm JOIN {$p}posts po ON po.ID=pm.post_id AND po.post_type IN('product','product_variation') WHERE pm.meta_key='_sku' AND pm.meta_value<>''");
  $map=array(); foreach($sk as $r){ $map[trim((string)$r->sku)]=array((int)$r->post_id,$r->post_type,$r->post_status); }
  $gid=$wpdb->get_results("SELECT pm.meta_value g, pm.post_id FROM {$p}postmeta pm JOIN {$p}posts po ON po.ID=pm.post_id AND po.post_type='product' AND po.post_status='publish' WHERE pm.meta_key='_global_unique_id' AND pm.meta_value<>''");
  $gmap=array(); foreach($gid as $r){ $gmap[trim((string)$r->g)]=array((int)$r->post_id,'product','publish'); }
  $bak=get_option('ps_s1637_bak',array());
  $stock=function($pid,$q) { $pr=wc_get_product($pid); if(!$pr) return false; $pr->set_manage_stock(true); $pr->set_stock_quantity((int)$q); $pr->save(); return true; };
  if('V'!==$f){
    $eil=array_values(array_filter(explode("\n",gzdecode(base64_decode('')))));
    $n=(int)substr($f,1); $chunk=array_slice($eil,$n*180,180);
    $st=array('partija'=>0,'stock'=>0,'own'=>0,'praleista'=>0,'sumuota'=>0,'klaidos'=>array());
    $agg=array(); $seen=get_option('ps_s1637_seen',array());
    foreach($chunk as $l){ $c=explode(';',$l); $s=trim($c[0]); $e=trim($c[1]); $q=(int)$c[2]; $sav=(float)$c[3];
      if(strpos($s,'gift-coupon')===0 || preg_match('/-dp\d*$/i',$s)){ $st['praleista']++; continue; }
      $hit=$map[$s] ?? null;
      if(!$hit && 'PET'===substr($s,0,3)) $hit=$map[substr($s,3)] ?? null;
      if(!$hit && $e!=='') $hit=$gmap[$e] ?? null;
      if(!$hit || $hit[2]!=='publish' || $hit[1]!=='product'){ $st['praleista']++; continue; }
      $pid=$hit[0];
      if(isset($agg[$pid])||isset($seen[$pid])){ $agg[$pid]=array(($agg[$pid][0]??$seen[$pid][0]??0)+$q, max($agg[$pid][1]??0,$sav)); $st['sumuota']++; continue; }
      $agg[$pid]=array($q,$sav);
    }
    foreach($agg as $pid=>$a){ list($q,$sav)=$a; $seen[$pid]=array($q,$sav);
      $wpdb->query($wpdb->prepare("DELETE FROM {$p}ps_partijos WHERE product_id=%d AND pastaba LIKE 'Pradinis likutis T-0%%'",$pid));
      $pr=wc_get_product($pid);
      if(!$pr || $pr->is_type('variable')){ $st['praleista']++; continue; }
      if($sav<=0) $sav=(float)get_post_meta($pid,'_cost_price',true);
      $tiek = get_post_meta($pid,'_vf_qty',true)!=='' || get_post_meta($pid,'_zb_qty',true)!=='';
      if($tiek){ $st['praleista']++; continue; } // T-0: ZB/VF NEKELIAM (Raimio sprendimas S1632)
      if(!isset($bak[$pid])) $bak[$pid]=array('s'=>get_post_meta($pid,'_stock',true),'o'=>get_post_meta($pid,'_own_stock_qty',true));
      if($tiek){
        if($sav>0){ update_post_meta($pid,'_own_stock_qty',0);
          $r=Petshop_Partijos::priimti($pid,array('kiekis'=>$q,'savikaina'=>$sav,'valiuta'=>'EUR','tiekejas'=>'eShoprent','importuota'=>1,'pastaba'=>'Pradinis likutis T-0'));
          if(is_wp_error($r)){ $st['klaidos'][]=$pid.':'.$r->get_error_code(); } else $st['own']++;
        } else { update_post_meta($pid,'_own_stock_qty',$q); $st['own']++; }
      } else {
        if($sav>0){ $stock($pid,0);
          $r=Petshop_Partijos::priimti($pid,array('kiekis'=>$q,'savikaina'=>$sav,'valiuta'=>'EUR','tiekejas'=>'eShoprent','importuota'=>1,'pastaba'=>'Pradinis likutis T-0'));
          if(is_wp_error($r)){ $st['klaidos'][]=$pid.':'.$r->get_error_code(); $stock($pid,$q); } else $st['partija']++;
        } else { $stock($pid,$q); $st['stock']++; }
      }
    }
    update_option('ps_s1637_bak',$bak,false); update_option('ps_s1637_seen',$seen,false);
    $o['chunk']=$n; $o['eiluciu']=count($chunk); $o['st']=$st; $o['klaidu']=count($st['klaidos']);
  } else {
    $norm=function($s){ $s=mb_strtolower(trim($s)); return str_replace(array('ė','ž','š','ų','ū','į','ą','č',' '),array('e','z','s','u','u','i','a','c',''),$s); };
    $st=array('kodu'=>0,'atributu'=>0,'praleista'=>0,'klaidos'=>array());
    foreach(array_filter(explode("\n",gzdecode(base64_decode('')))) as $l){ $c=explode(';',$l); list($bs,$at,$re,$vk,$q)=array(trim($c[0]),$c[1],trim($c[2]),trim($c[3]),(int)$c[4]);
      if(strpos($bs,'gift')===0){ $st['praleista']++; continue; }
      $vid=0;
      if(isset($map[$bs])){ $pr=wc_get_product($map[$bs][0]);
        if($pr && $pr->is_type('variable')){ foreach($pr->get_children() as $cid){ $v=wc_get_product($cid); if(!$v)continue;
          foreach($v->get_attributes() as $tax=>$slug){ $t=get_term_by('slug',$slug,$tax); if($norm($t?$t->name:$slug)===$norm($re)){ $vid=$cid; $kaip='atributu'; break 2; } } } } }
      if(!$vid && $vk!=='' && isset($map[$vk]) && $map[$vk][1]==='product_variation'){ $vid=$map[$vk][0]; $kaip='kodu'; }
      if(!$vid){ $st['praleista']++; continue; }
      if(get_post_meta($vid,'_vf_qty',true)!==''){ $st['praleista']++; $st['klaidos'][]=$vid.':vf_var'; continue; }
      if(!isset($bak[$vid])) $bak[$vid]=array('s'=>get_post_meta($vid,'_stock',true));
      if($stock($vid,$q)) $st[$kaip]++; else $st['klaidos'][]=$vid.':save';
    }
    update_option('ps_s1637_bak',$bak,false);
    $o['st']=$st;
    $o['partiju_lentele']=(int)$wpdb->get_var("SELECT COUNT(*) FROM {$p}ps_partijos");
    $o['partiju_s1632']=(int)$wpdb->get_var("SELECT COUNT(*) FROM {$p}ps_partijos WHERE pastaba LIKE 'Pradinis likutis T-0%'");
    $o['bak_n']=count($bak);
    $o['ping']=wp_remote_retrieve_response_code(wp_remote_get(home_url('/'),array('timeout'=>30,'sslverify'=>false)));
  }
  header('Content-Type: application/json'); echo json_encode($o,JSON_UNESCAPED_UNICODE); exit;
},99);
